INSERT INTO questions (position, sort_order, question, option_a, option_b, option_c, option_d, option_e, answer_key) VALUES
('perawat', 21, 'Sesuai dengan standar WHO, perawat wajib menerapkan Five Moments For Hand Hygiene. Momen kedua untuk melakukan cuci tangan adalah...', 'Sebelum menyentuh pasien', 'Sebelum melakukan tindakan aseptik', 'Setelah terkena cairan tubuh pasien', 'Setelah menyentuh pasien', 'Setelah menyentuh lingkungan sekitar pasien', 'B'),
('perawat', 22, 'Seorang pasien laki-laki berusia 45 tahun baru saja masuk ruang rawat inap. Manakah kombinasi indikator yang paling tepat dan aman digunakan oleh perawat untuk mengidentifikasi pasien tersebut sebelum memberikan obat?', 'Nama pasien dan nomor kamar', 'Nomor rekam medis dan nomor tempat tidur', 'Nama lengkap pasien dan tanggal lahir', 'Nama panggilan pasien dan diagnosa medis', 'Nama dokter yang merawat dan nama ruangan', 'C'),
('perawat', 23, 'Perawat A akan melaporkan kondisi pasien yang mengalami penurunan saturasi oksigen secara mendadak kepada dokter penanggung jawab melalui telepon. Format komunikasi efektif yang harus digunakan adalah...', 'SOAP', 'BAR', 'SBAR', 'TBAK', 'Dokumentasi proses', 'C'),
('perawat', 24, 'Setelah menerima instruksi verbal dari dokter melalui telepon mengenai dosis obat emergensi, langkah keselamatan pasien (patient safety) yang wajib dilakukan perawat adalah...', 'Langsung menyuntikkan obat sesuai ingatan', 'Meminta perawat lain untuk mendengarkan ulang di telepon', 'Menulis instruksi, membaca kembali, dan meminta konfirmasi ulang (TBAK)', 'Menunggu dokter datang ke ruangan untuk menulis resep terlebih dahulu', 'Mencatat di buku operan saja', 'C'),
('perawat', 25, 'Seorang pasien rawat inap diidentifikasi oleh tim medis memiliki riwayat alergi berat terhadap obat golongan penisilin. Warna gelang identifikasi khusus yang harus dipasangkan pada perawat pasien tersebut adalah...', 'Gelang warna Kuning', 'Gelang warna Merah Muda', 'Gelang warna Biru', 'Gelang warna Merah', 'Gelang warna Ungu', 'D'),
('perawat', 26, 'Perawat selesai melakukan tindakan perawatan luka (dressing) pada pasien dengan gangren. Kassa yang terkontaminasi oleh darah dan nanah harus dibuang ke dalam...', 'Plastik hitam (Limbah domestik)', 'Plastik kuning (Limbah infeksius)', 'Plastik ungu (Limbah sitostatika)', 'Safety Box (Limbah benda tajam)', 'Plastik merah (Limbah radioaktif)', 'B'),
('perawat', 27, 'Tindakan pertama yang paling tepat dan segera dilakukan oleh seorang perawat jika tidak sengaja tertusuk jarum suntik bekas pakai (needle stick injury) saat bertugas adalah...', 'Menghisap darah dari luka tusukan dengan mulut', 'Membilas luka di air mengalir menggunakan sabun atau antiseptik', 'Membiarkan saja dan langsung menutupnya dengan plester', 'Langsung memencet luka sekeras-kerasnya agar darah keluar banyak', 'Pergi ke laboratorium untuk cek darah tanpa membersihkan luka', 'B'),
('perawat', 28, 'Seorang pasien dewasa mendapatkan instruksi pemenuhan cairan infus NaCl 0,9% sebanyak 500 ml untuk dihabiskan dalam waktu 8 jam. Jika faktor tetes makro yang digunakan adalah 20 tetes/ml, berapakah kecepatan tetesan infus yang harus diatur oleh perawat?', '15 tetes/menit', '21 tetes/menit', '31 tetes/menit', '42 tetes/menit', '60 tetes/menit', 'B'),
('perawat', 29, 'Pasien anak membutuhkan cairan Dextrose 5% sebanyak 240 ml yang harus habis dalam waktu 4 jam menggunakan infus set mikro (faktor tetes 60 tetes/ml). Berapakah jumlah tetesan per menit (tpm) obat tersebut?', '20 tpm', '30 tpm', '40 tpm', '60 tpm', '80 tpm', 'D'),
('perawat', 30, 'Dokter memberikan instruksi pemberian Ceftriaxone 250 mg melalui injeksi Intravena. Sediaan obat di dalam vial adalah 1 gram (1000 mg) yang kemudian dilarutkan/dioplos dengan 10 ml Aqua Bidest. Berapakah volume obat yang harus dihisap perawat ke dalam spuit?', '1 ml', '2,5 ml', '4 ml', '5 ml', '7,5 ml', 'B'),
('perawat', 31, 'Seorang anak diresepkan obat sirup Paracetamol dengan dosis 120 mg secara oral. Sediaan sirup yang tersedia di botol obat adalah 160 mg per 5 ml. Berapakah volume sirup yang harus dituangkan perawat ke dalam sendok takar?', '2,5 ml', '3 ml', '3,75 ml', '4,2 ml', '5 ml', 'C'),
('perawat', 32, 'Ketika hendak memberikan obat kepada pasien, perawat melakukan verifikasi ulang mengenai rute pemberian (misal: Oral, IV, IM, SC). Langkah ini termasuk dalam penerapan prinsip "Benar" pemberian obat, yaitu...', 'Benar Pasien', 'Benar Dosis', 'Benar Waktu', 'Benar Rute', 'Benar Dokumentasi', 'D'),
('perawat', 33, 'Seorang pasien laki-laki berusia 60 tahun dirawat dengan keluhan sesak napas berat. Hasil pemeriksaan menunjukkan frekuensi napas 26 x/menit dan saturasi oksigen (SpO₂) terbaca 90% pada udara kamar. Dokter menginstruksikan pemberian oksigen konsentrasi rendah-sedang dengan laju aliran 4 Liter/menit. Manakah jenis alat pemberian oksigen yang paling tepat disiapkan oleh perawat?', 'Nasal Kanul', 'Simple Mask (Masker Oksigen Sederhana)', 'Rebreathing Mask (RBM)', 'Non-Rebreathing Mask (NRBM)', 'Masker Venturi', 'D'),
('perawat', 34, 'Perawat sedang menghitung balance cairan seorang pasien dalam 24 jam. Komponen manakah di bawah ini yang dikategorikan ke dalam Output (cairan keluar) tidak nyata atau Insensible Water Loss (IWL)?', 'Urine', 'Cairan Drain lambung', 'Uap air dari pernapasan dan keringat', 'Feses encer', 'Muntah', 'C'),
('perawat', 35, 'Seorang pasien laki-laki dewasa memiliki berat badan 60 kg dirawat dengan bed rest total. Berapakah estimasi nilai IWL (Insensible Water Loss) normal pasien tersebut dalam waktu 24 jam jika dihitung menggunakan rumus standar (15 ml/kgBB/24 jam)?', '500 ml', '750 ml', '900 ml', '1200 ml', '1500 ml', 'C'),
('perawat', 36, 'Menurut pedoman Resusitasi Jantung Paru (RJP) terbaru untuk pasien dewasa yang mengalami henti jantung, berapakah rasio kompresi dada dan ventilasi yang benar dengan 2 orang penolong?', '15 : 1', '15 : 2', '5 : 1', '30 : 2', '30 : 5', 'D'),
('perawat', 37, 'Kompresi dada yang efektif pada tindakan RJP dewasa harus dilakukan dengan kecepatan dan kedalaman tertentu. Manakah kriteria yang tepat?', 'Kecepatan 100-120 kali/menit, kedalaman 5-6 cm', 'Kecepatan 80-100 kali/menit, kedalaman 3-4 cm', 'Kecepatan >130 kali/menit, kedalaman 4-5 cm', 'Kecepatan 60-80 kali/menit, kedalaman 5-6 cm', 'Kecepatan 100-120 kali/menit, kedalaman 7-8 cm', 'A'),
('perawat', 38, 'Anda sedang berjalan di koridor rumah sakit dan melihat seorang pengunjung tiba-tiba terjatuh dan tidak sadarkan diri. Langkah pertama yang harus Anda lakukan sesuai algoritma BHD adalah...', 'Langsung melakukan kompresi dada', 'Memberikan napas buatan dua kali', 'Memastikan keamanan lingkungan, diri sendiri, dan pasien (Danger)', 'Mencari bantuan alat Defibrilator (AED)', 'Memeriksa denyut nadi karotis pasien', 'C'),
('perawat', 39, 'Seorang pasien korban kecelakaan lalu lintas dibawa ke IGD dalam kondisi penurunan kesadaran. Saat perawat melakukan inspeksi jalan napas, terdengar suara napas tambahan berupa gargling (seperti berkumur). Hal ini menandakan adanya sumbatan jalan napas berupa...', 'Pangkal lidah yang jatuh ke belakang', 'Spasme jalan napas atas', 'Cairan, darah, atau sekret lambung', 'Benda padat seperti makanan', 'Edema pada laring', 'C'),
('perawat', 40, 'Sistem aktivasi kedaruratan di rumah sakit memiliki kode penamaan warna khusus. Jika terjadi kondisi henti jantung atau henti napas pada pasien di bangsal, kode darurat yang harus segera diumumkan adalah...', 'Code Red', 'Code Blue', 'Code Pink', 'Code Black', 'Code Yellow', 'B'),
('perawat', 41, 'Seorang pasien perempuan berusia 28 tahun dirawat di ruang bedah pasca operasi laparaktomi hari pertama. Saat Anda melakukan observasi, pasien mengeluh nyeri hebat pada area luka operasi dengan skala 7 (1-10). Data tanda-tanda vital menunjukkan TD: 140/90 mmHg, Nadi: 110 x/menit, Pernapasan: 24 x/menit. Berdasarkan prioritas masalah keperawatan, diagnosis utama yang tepat adalah...', 'Nyeri akut berhubungan dengan agen pencedera fisik (prosedur operasi)', 'Pola napas tidak efektif berhubungan dengan kecemasan', 'Risiko infeksi berhubungan dengan efek prosedur invasif', 'Gangguan mobilitas fisik berhubungan dengan kelemahan anggota gerak', 'Defisit nutrisi berhubungan dengan penurunan nafsu makan', 'C'),
('perawat', 42, 'Jalur pemberian obat emergensi yang paling diutamakan pada pasien henti jantung jika akses intravena (IV) perifer sama sekali tidak dapat dipasang adalah...', 'Intramuskular (IM)', 'Subkutan (SC)', 'Intraoseus (IO)', 'Intradermal (ID)', 'Melalui NGT', 'C'),
('perawat', 43, 'Tahapan proses keperawatan yang berfokus pada pengumpulan data, validasi data, dan pengelompokan data pasien dinamakan tahap...', 'Pengkajian', 'Diagnosis keperawatan', 'Intervensi', 'Implementasi', 'Evaluasi', 'A'),
('perawat', 44, 'Manakah di bawah ini yang dikategorikan sebagai Data Subjektif dalam dokumentasi keperawatan?', 'Tekanan darah pasien 130/80 mmHg', 'Hasil laboratorium Hb 10 gr/dl', 'Pasien mengatakan badannya terasa lemas dan mual', 'Tampak luka robek pada lengan kanan pasien', 'Hasil rontgen thorax menunjukkan kardiomegali', 'C'),
('perawat', 45, 'Seorang pasien mengalami stroke dan mengalami kelumpuhan total pada kedua kaki dan tangannya (tetraplegia). Untuk mencegah timbulnya cedera luka tekan (dekubitus), intervensi utama perawat adalah...', 'Memberikan lotion setiap jam', 'Memasang selimut tebal pada pasien', 'Mengubah posisi tidur pasien (alih baring) setiap 2 jam', 'Memijat area tonjolan tulang yang memerah', 'Menjaga pasien agar tetap telentang sepanjang hari', 'C'),
('perawat', 46, 'Perawat mengkaji tingkat kesadaran pasien dengan hasil: pasien membuka mata dengan spontan, merespon verbal dengan kata-kata yang jelas, dan mampu menghindari  nyeri yang diberikan. Berapakah total skor GCS (Glasgow Coma Scale) pasien tersebut?', 'GCS 8', 'GCS 9', 'GCS 15', 'GCS 13', 'GCS 14', 'C'),
('perawat', 47, 'Seorang pasien terpasang kateter urine menetap hari ke-2. Manakah posisi kantung urine (urinabag) yang paling tepat untuk mencegah terjadinya infeksi saluran kemih (ISK) akibat aliran balik (retrograde)?', 'Diletakkan sejajar di atas dada pasien', 'Digantung di tiang infus setinggi kepala pasien', 'Diletakkan langsung di lantai ruangan', 'Digantung di tepi tempat tidur dengan posisi lebih rendah dari kandung kemih', 'Diikatkan di paha pasien sejajar dengan pinggang', 'D'),
('perawat', 48, 'Sebelum memasukkan slang NGT (Nasogastric Tube) ke dalam hidung pasien, perawat wajib mengukur panjang slang terlebih dahulu. Cara pengukuran konvensional yang benar adalah diukur dari...', 'Ujung hidung ke daun telinga, lalu dilanjutkan ke prosesus xipoideus', 'Dahi ke hidung, lalu ke pusat perut', 'Batas rambut kepala ke hidung, lalu ke dagu', 'Ujung mulut langsung ditarik ke pusat perut pasien', 'Daun telinga kanan langsung ke daun telinga kiri', 'A'),
('perawat', 49, 'Berdasarkan Standar Diagnosis Keperawatan Indonesia (SDKI), komponen penulisan diagnosis keperawatan aktual yang lengkap harus terdiri dari unsur...', 'Masalah (Problem) saja', 'Penyebab (Etiology) saja', 'Tanda/Gejala (Symptom) saja', 'Masalah (Problem) dan Faktor Risiko', 'Masalah (Problem), Penyebab (Etiology), dan Tanda/Gejala (Symptom)', 'E'),
('perawat', 50, 'Di ruang rawat inap terdapat 5 pasien yang menjadi tanggung jawab Anda. Manakah kondisi pasien yang harus Anda prioritaskan terlebih dahulu untuk dilakukan tindakan keperawatan?', 'Pasien yang mengeluh infusnya macet tetapi tidak bengkak', 'Pasien pasca operasi hari ke-3 yang meminta diganti perban', 'Pasien diabetes yang meminta jadwal makan siangnya', 'Pasien asma yang tiba-tiba mengeluh sesak napas berat dan gelisah', 'Pasien yang sudah diperbolehkan pulang dan meminta surat kontrol', 'D'),
('administrasi', 1, 'Saat menerima telepon dari pihak luar, tindakan pertama yang tepat adalah...', 'Mengangkat telepon dan menyebutkan salam serta identitas instansi', 'Langsung menanyakan keperluan tanpa salam', 'Membiarkan telepon berdering', 'Meminta penelepon menghubungi kembali', 'Menutup telepon jika sedang sibuk', 'A'),
('administrasi', 2, 'Dokumen yang berisi data pribadi pelamar sebaiknya...', 'Dibagikan kepada seluruh karyawan', 'Disimpan dengan aman dan hanya diakses pihak berwenang', 'Ditinggalkan di meja umum', 'Diunggah ke media sosial', 'Dikirim ke pihak luar tanpa izin', 'B'),
('administrasi', 3, 'Jika menemukan kesalahan penulisan data pada dokumen resmi, Anda sebaiknya...', 'Mengabaikannya', 'Menghapus seluruh dokumen', 'Memverifikasi dan memperbaikinya sesuai prosedur', 'Menyalahkan rekan kerja', 'Mengirim dokumen tanpa perbaikan', 'C'),
('administrasi', 4, 'Manakah contoh komunikasi tertulis yang profesional?', 'Menggunakan bahasa yang jelas dan sopan', 'Menulis seluruh pesan dengan huruf kapital', 'Menggunakan singkatan yang sulit dipahami', 'Mengirim pesan tanpa subjek', 'Menggunakan bahasa tidak sopan', 'A'),
('administrasi', 5, 'Apa yang perlu dilakukan sebelum mengirim email dengan lampiran?', 'Menghapus subjek email', 'Memastikan penerima, isi, dan lampiran sudah benar', 'Mengirim ke semua kontak', 'Menulis kata sandi di isi email', 'Mengabaikan ukuran lampiran', 'B'),
('administrasi', 6, 'Ketika menerima beberapa tugas dengan tenggat berbeda, langkah yang tepat adalah...', 'Mengerjakan secara acak', 'Menunggu sampai semua tenggat tiba', 'Menyusun prioritas berdasarkan urgensi dan kepentingan', 'Menolak semua tugas', 'Hanya mengerjakan tugas yang disukai', 'C'),
('administrasi', 7, 'Tujuan utama pengarsipan dokumen yang teratur adalah...', 'Memperbanyak dokumen', 'Mempersulit pencarian', 'Memudahkan penyimpanan dan penemuan kembali dokumen', 'Menghindari penggunaan komputer', 'Menghapus seluruh dokumen lama', 'C'),
('administrasi', 8, 'Seseorang meminta informasi yang bukan kewenangan Anda untuk dibagikan. Apa yang sebaiknya dilakukan?', 'Memberikan semua informasi', 'Mengarahkan permintaan kepada pihak yang berwenang', 'Menyebarkan permintaan tersebut', 'Menebak informasi yang diminta', 'Mengabaikan aturan kerahasiaan', 'B'),
('administrasi', 9, 'Dalam pengolahan data, ketelitian diperlukan untuk...', 'Mengurangi risiko kesalahan informasi', 'Memperlambat pekerjaan tanpa manfaat', 'Menghindari kerja sama', 'Menghilangkan kebutuhan pemeriksaan', 'Mengganti seluruh prosedur', 'A'),
('administrasi', 10, 'Jika tidak memahami instruksi pekerjaan, tindakan terbaik adalah...', 'Menebak tanpa memeriksa', 'Mengabaikan pekerjaan', 'Meminta klarifikasi kepada pemberi instruksi', 'Menunggu orang lain menyelesaikan', 'Menyebarkan instruksi yang belum jelas', 'C');
